 wild=['\U0001f9a1 Badger', '\U0001f43f\ufe0f Pine marten', '\U0001f98c Roe deer', '\U0001fab5 Great spotted woodpecker', '\U0001f333 Pedunculate oak \u00b7 Black alder \u00b7 Beech'],
